import React from 'react';
import {
  TimePicker as ArcoTimePicker,
  TimePickerProps as ArcoTimePickerProps,
  TimeRangePickerProps as ArcoTimeRangePickerProps
} from '@arco-design/web-react';
import { connect, mapProps, mapReadPretty } from '@formily/react';
import dayjs from 'dayjs';
import { PreviewText } from '..';

type ComposedTimePicker = React.FC<ArcoTimePickerProps> & {
  RangePicker?: React.FC<ArcoTimeRangePickerProps>;
};

const mapTimeFormat = function () {
  const dayjsAble = (value: any, format: string) =>
    (Array.isArray(value) ? value.map(val => dayjs(val).format(format)) : value ? dayjs(value).format(format) : value);

  return (props: any) => {
    const format = props.format || 'HH:mm:ss';
    const { onChange } = props;
    return {
      ...props,
      format,
      onChange: (dateString: string | string[]) => {
        onChange(dateString);
      },
    };
  };
};

export const TimePicker: ComposedTimePicker = connect(
  ArcoTimePicker,
  mapProps(mapTimeFormat()),
  mapReadPretty(props => {
    const format = props.format || 'HH:mm:ss';
    return <PreviewText.DatePicker {...props} format={format} />;
  })
);

export const RangePicker = connect(
  ArcoTimePicker.RangePicker,
  mapProps(mapTimeFormat()),
  mapReadPretty(props => {
    const format = props.format || 'HH:mm:ss';
    return <PreviewText.DatePicker {...props} format={format} />;
  })
);

export default TimePicker;
